/* بيانات باب itam: تُحمَّل عند أول فتح للقسم */
window.ITAM = {"ch":[{"id":"miskin","t":"إطعام المسكين واليتيم والأسير","d":"الآيات التي ذكرت الإطعام في وصف الأبرار وفي اقتحام العقبة، وبيّنت من تُطعِمهم النفقة، وأن الله هو المطعِم الذي لا يُطعَم."},{"id":"hadd","t":"الحضّ على طعام المسكين وذمّ من تركه","d":"الآيات التي قرنت ترك الحضّ على طعام المسكين بالتكذيب وعدم الإيمان، وذكرت ذلك في أسباب العذاب، وفي أصحاب الجنة الذين منعوا المساكين."},{"id":"dayf","t":"الضيف والضيافة","d":"ما ورد في القرآن من قصص الضيافة: ضيف إبراهيم عليه السلام، وضيف لوط عليه السلام، وأهل القرية الذين أبوا أن يضيّفوا، ويوسف عليه السلام وحسن الإنزال، وابن السبيل، وآداب الأكل في البيوت وعند الدعوة."},{"id":"ahkam","t":"الإطعام في الأحكام","d":"الآيات التي جعلت الإطعام كفارةً أو فديةً أو نصيباً من الهدي: كفارة اليمين، وكفارة الظهار، والأكل من الهدي وإطعام البائس."},{"id":"siyam","t":"الصيام والطعام","d":"آيات الصيام فيما يتصل بالطعام والشراب: حكمة الصيام، وفدية الإطعام عن الصائم، والأكل والشرب إلى طلوع الفجر."}],"tp":[{"id":"asir","ch":"miskin","t":"«ويطعمون الطعام على حبه مسكيناً ويتيماً وأسيراً»","e":"وصف الأبرار بإطعام الطعام على حبه مسكيناً ويتيماً وأسيراً لوجه الله.","ay":[[76,5,12]],"q":[{"bk":"saadi","s":76,"ay":8,"x":"{ويطعِمونَ الطَّعامَ على حبِّه}؛ أي: وهم في حال يحبُّون فيها المال والطعام، لكنَّهم قدَّموا محبَّة الله على محبَّة نفوسهم، ويتحرَّوْن في إطعامهم أولى الناس وأحوجَهم، {مسكيناً ويتيماً وأسيراً}: ويقصدون بإنفاقهم وإطعامهم وجهَ الله تعالى، ويقولون بلسان الحال:{إنَّما نطعِمُكم لوجه الله لا نريدُ منكم جزاءً ولا شكوراً}؛ أي: لا جزاءً ماليًّا ولا ثناءً قوليًّا، {إنا نخاف من ربِّنا يوماً عبوساً}؛ أي: شديد الجهمة والشرِّ، {قمطريراً}؛ أي: ضنكاً ضيقاً.","w":"السعدي","en":"\"And they feed food, despite their love for it\" — that is, while they love wealth and food, they put the love of Allah before the love of themselves, and they seek out the most deserving and needy of people to feed — \"the poor, the orphan and the captive\". They intend by their spending and feeding the face of Allah the Exalted, and they say in the tongue of their state: \"We feed you only for the face of Allah; we want from you neither reward nor thanks\" — that is, neither reward in wealth nor praise in words — \"Indeed, we fear from our Lord a day austere and distressful\" — severe in its frowning and its evil, \"and distressful\" meaning constricting."}],"h":["tutim"]},{"id":"aqaba","ch":"miskin","t":"«أو إطعام في يوم ذي مسغبة يتيماً ذا مقربة أو مسكيناً ذا متربة»","e":"بيان العقبة التي لم يقتحمها الإنسان، ومنها الإطعام في يوم ذي مسغبة.","ay":[[90,11,18]],"q":[{"bk":"saadi","s":90,"ay":12,"x":"ثم فسَّر هذه العقبة بقوله: {فكُّ رقبةٍ}؛ أي: فكُّها من الرقِّ بعتقها أو مساعدتها على أداء كتابتها، ومن باب أولى فكاك الأسير المسلم عند الكفار، {أو إطعامٌ في يوم ذي مَسۡغَبَةٍ}؛ أي: مجاعةٍ شديدةٍ؛ بأن يطعم وقت الحاجة أشدَّ الناس حاجةً، {يتيماً ذا مَقۡرَبَةٍ}؛ أي: جامعاً بين كونه يتيماً وفقيراً ذا قرابة، {أو مسكيناً ذا مَتۡرَبَةٍ}؛ أي: قد لزق بالتراب من الحاجة والضَّرورة.","w":"السعدي","en":"Then He explained this steep path by His words: \"the freeing of a slave\" — that is, freeing him from slavery by emancipating him or helping him pay off his contract, and all the more so ransoming a Muslim captive from the disbelievers — \"or feeding on a day of severe hunger\" — that is, great famine, so that he feeds at the time of need the people most in need — \"an orphan of kin\" — one who combines being an orphan, poor and related — \"or a poor person in dust\" — who is stuck to the dust from need and hardship."}],"h":["jai"]},{"id":"mutim","ch":"miskin","t":"الله المطعِم: «وهو يطعم ولا يطعم» و«ما أريد أن يطعمون»","e":"الله هو الذي يطعِم ولا يُطعَم، وهو الغني عن إطعام خلقه.","ay":[[6,14,14],[51,56,58],[106,3,4]],"q":[{"bk":"saadi","s":51,"ay":57,"x":"فما يريد {منهم من رزقٍ وما} يريدُ {أن يطعمونِ}: تعالى الغنيُّ المغني عن الحاجة إلى أحدٍ بوجه من الوجوه، وإنَّما جميع الخلق فقراءُ إليه في جميع حوائجهم ومطالبهم الضروريَّة وغيرها.","w":"السعدي","en":"He \"wants from them no provision, nor do I want them to feed Me\": the Exalted, the Self-Sufficient, who enriches, is free of need of anyone in any way; all creation are poor before Him in all their needs and necessary requests and others."},{"bk":"saadi","s":6,"ay":14,"x":"{قل} لهؤلاء المشركين بالله: {أغيرَ الله أتَّخِذُ وليًّا}: من هؤلاء المخلوقات العاجزة يتولاَّني وينصُرُني؛ فلا أتَّخذ من دونه تعالى وليًّا؛ لأنَّه {فاطر السموات والأرض}؛ أي: خالقهما ومدبِّرهما، {وهو يُطۡعِمُ ولا يُطۡعَمُ}؛ أي: وهو الرازق لجميع الخلق من غير حاجةٍ منه تعالى إليهم؛ فكيف يَليقُ أن أتَّخِذَ وليًّا غير الخالق الرازق الغني الحميد.","w":"السعدي","en":"\"Say\" to these polytheists: \"Is it other than Allah I should take as a protector\" from among these helpless creatures who would guard and support me? I will not take as protector anyone besides Him, for He is \"Creator of the heavens and the earth\", that is, their Creator and Disposer, \"and it is He who feeds and is not fed\" — that is, He is the Provider of all creation without any need on His part for them. So how could it be fitting for me to take as protector anyone but the Creator, the Provider, the Self-Sufficient, the Praiseworthy?"}],"h":[]},{"id":"nafaqa","ch":"miskin","t":"«يسألونك ماذا ينفقون قل ما أنفقتم من خير فللوالدين والأقربين واليتامى والمساكين»","e":"سؤال الناس عن النفقة وجوابه بذكر من تُصرف إليهم، ومنهم اليتامى والمساكين وابن السبيل.","ay":[[2,215,215],[4,8,8]],"q":[{"bk":"saadi","s":2,"ay":215,"x":"أي: يسألونك عن النفقة وهذا يعم السؤال عن المنفَق والمنفَق عليه، فأجابهم عنها فقال:{قل ما أنفقتم من خير}؛ أي: مال قليل أو كثير فأولى الناس به وأحقهم بالتقديم أعظمهم حقًّا عليك، وهم الوالدان الواجب برهما والمحرم عقوقهما، ومن أعظم برهما، النفقة عليهما، ومن أعظم العقوق ترك الإنفاق عليهما، ولهذا كانت النفقة عليهما واجبة على الولد الموسر، ومن بعد الوالدين الأقربون على اختلاف طبقاتهم، الأقرب، فالأقرب، على حسب القرب والحاجة، فالإنفاق عليهم صدقة وصلة {واليتامى}؛ وهم الصغار الذين لا كاسب لهم فهم في مظنة الحاجة، لعدم قيامهم بمصالح أنفسهم وفقد الكاسب، فوصى الله بهم العباد رحمة منه بهم ولطفاً {والمساكين}؛ وهم أهل الحاجات وأرباب الضرورات الذين أسكنتهم الحاجة، فينفَق عليهم لدفع حاجاتهم وإغنائهم {وابن السبيل}؛ أي …","w":"السعدي","en":"That is: they ask you about spending, and this includes the question about what is spent and on whom it is spent. He answered them: \"Whatever you spend of good\" — wealth, little or much — then the most deserving of people for it, and the first to be given priority, are those with the greatest right over you: the parents, whom it is obligatory to treat with kindness and forbidden to wrong, and among the greatest kindness to them is spending on them, as among the greatest wrongs is to stop spending on them, which is why spending on them is obligatory on a well-off son. After the parents are the near relatives in their various degrees, the nearest first, according to nearness and need; spending on them is charity and keeping of ties. \"And the orphans\" — the young who have no earner, who are liable to need because they cannot see to their own interests and have lost the earner, so Allah charged His servants with them out of mercy and kindness toward them; \"and the poor\" — those with needs and necessities, whom need has made destitute, so they are spent on to meet their needs and enrich them; \"and the wayfarer\" — that is …"}],"h":["ijtama"]},{"id":"maun","ch":"hadd","t":"«ولا يحض على طعام المسكين»: سورة الماعون","e":"ذكر ترك الحضّ على طعام المسكين في وصف المكذّب بالدين.","ay":[[107,1,7]],"q":[{"bk":"saadi","s":107,"ay":3,"x":"{ولا يحضُّ}: غيره {على طعام المسكينِ}: ومن باب أولى أنَّه بنفسه لا يطعم المسكين.","w":"السعدي","en":"\"And does not urge\" others \"to the feeding of the poor\": all the more so, he himself does not feed the poor."},{"bk":"saadi","s":107,"ay":3,"x":"وفي هذه السورة الحثُّ على إطعام اليتيم والمساكين، والتَّحضيض على ذلك، ومراعاة الصَّلاة، والمحافظة عليها، وعلى الإخلاص فيها، وفي سائر الأعمال ، والحثُّ على فعل المعروف، وبذل الأمور الخفيفة كعارية الإناء والدَّلو والكتاب ونحو ذلك؛ لأنَّ الله ذمَّ من لم يفعل ذلك.","w":"السعدي","en":"This surah contains the urging of feeding the orphan and the poor and encouraging it, along with attention to prayer, guarding it and sincerity in it and in all deeds, and the urging of doing good and giving light things such as lending a vessel, a bucket, a book and the like; for Allah blamed the one who does not do that."}],"h":["istatam"]},{"id":"haqqa","ch":"hadd","t":"«إنه كان لا يؤمن بالله العظيم ولا يحض على طعام المسكين»","e":"ذكر ترك الحضّ على طعام المسكين في سبب عذاب صاحب الكتاب بشماله.","ay":[[69,25,37]],"q":[{"bk":"ibnkathir","s":69,"ay":34,"x":"وَقَوْلُهُ: ﴿إِنَّهُ كَانَ لَا يُؤْمِنُ بِاللَّهِ الْعَظِيمِ وَلا يَحُضُّ عَلَى طَعَامِ الْمِسْكِينِ﴾ أَيْ: لَا يَقُومُ بِحَقِّ اللَّهِ عَلَيْهِ مِنْ طَاعَتِهِ وَعِبَادَتِهِ، وَلَا يَنْفَعُ خَلْقَهُ وَيُؤَدِّي حَقَّهُمْ؛ فَإِنَّ لِلَّهِ عَلَى الْعِبَادِ أَنْ يُوَحِّدُوهُ وَلَا يُشْرِكُوا بِهِ شَيْئًا، وَلِلْعِبَادِ بَعْضُهُمْ عَلَى بَعْضٍ حَقُّ الْإِحْسَانِ وَالْمُعَاوَنَةِ عَلَى الْبِرِّ وَالتَّقْوَى؛ وَلِهَذَا أَمَرَ اللَّهُ بِإِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ، وَقُبِضَ النَّبَيُّ ﷺ وَهُوَ يَقُولُ: \"الصَّلَاةَ، وما ملكت أيمانكم\" .","w":"ابن كثير","en":"His words: \"Indeed, he did not believe in Allah, the Most Great, nor did he urge the feeding of the poor\" — that is, he did not fulfil Allah's right over him of obedience and worship, nor did he benefit His creation and give them their due. Allah has a right over servants that they affirm His oneness and not associate anything with Him, and servants have over one another the right of kindness and of helping one another in righteousness and piety. That is why Allah commanded the establishment of prayer and the giving of zakat, and the Prophet ﷺ passed away saying: \"The prayer, and those whom your right hands possess.\""},{"bk":"saadi","s":69,"ay":34,"x":"ثم التفت إلى ماله وسلطانه؛ فإذا هو وبالٌ عليه لم يقدِّم منه لآخرته ولا ينفعه لو افتدى به من العذاب شيئاً ، فيقول:{ما أغنى عنِّي مالِيَهۡ}؛ أي: ما نفعني لا في الدُّنيا ـ لم أقدِّم منه شيئاً ـ ولا في الآخرة؛ قد ذهب وقت نفعه، {هلك عني سُلطانِيَهۡ}؛ أي: ذهب واضمحلَّ، فلم تنفع الجنود ولا الكثرة ولا العَدَدُ ولا العُدَدُ ولا الجاه العريض، بل ذهب ذلك كله أدراج الرياح، وفاتت بسببه المتاجر والأرباح، وحضرت بدله الهموم والغموم والأتراح.","w":"السعدي","en":"Then he turns to his wealth and authority, and finds it a burden upon him; he sent nothing of it ahead for his Hereafter, and even if he ransomed himself with it from the punishment it would avail him nothing. So he says: \"My wealth has not availed me\" — it did not benefit me in this world, for I sent nothing ahead of it, nor in the Hereafter, for the time of its benefit has gone — \"My authority has gone from me\" — vanished and faded. Soldiers, numbers, equipment and wide standing did not help; rather it all went with the wind, and by it trade and profit were lost, and in their place came worries, griefs and sorrows."}],"h":[]},{"id":"fajr","ch":"hadd","t":"«كلا بل لا تكرمون اليتيم ولا تحاضون على طعام المسكين»","e":"ذكر ترك التحاضّ على طعام المسكين مع إكرام اليتيم وأكل التراث.","ay":[[89,15,20]],"q":[{"bk":"saadi","s":89,"ay":18,"x":"وأيضاً؛ فإنَّ وقوف همَّة العبد عند مراد نفسه فقط من ضعف الهمَّة، ولهذا لامَهُمُ الله على عدم اهتمامهم بأحوال الخلق المحتاجين، فقال:{كلاَّ بل لا تكرِمون اليتيمَ}: الذي فقد أباه وكاسبه واحتاج إلى جبر خاطره والإحسان إليه؛ فأنتُم لا تكرِمونه بل تهينونه، وهذا يدلُّ على عدم الرحمة في قلوبكم وعدم الرغبة في الخير، {ولا تحاضُّون على طعام المسكين}؛ أي: لا يحضُّ بعضكم بعضاً على إطعام المحاويج من الفقراء والمساكين ، وذلك لأجل الشحِّ على الدنيا ومحبَّتها الشديدة المتمكَّنة من القلوب.","w":"السعدي","en":"Moreover, a servant's ambition stopping at what his own self wants is a weakness of ambition, which is why Allah blamed them for their lack of concern for the conditions of the needy among creation, saying: \"No! But you do not honour the orphan\" — who has lost his father and provider and needs to have his heart mended and to be treated kindly; you do not honour him, rather you humiliate him, and this shows the lack of mercy in your hearts and of desire for good — \"and you do not urge one another to feed the poor\", that is, you do not urge one another to feed the needy among the poor, and that is because of miserliness over this world and an intense love of it firmly lodged in the hearts."},{"bk":"ibnkathir","s":89,"ay":18,"x":"﴿وَلا تَحَاضُّونَ عَلَى طَعَامِ الْمِسْكِينِ﴾ يَعْنِي: لَا يَأْمُرُونَ بِالْإِحْسَانِ إِلَى الْفُقَرَاءِ وَالْمَسَاكِينِ، وَيُحِثُّ بَعْضُهُمْ عَلَى بَعْضٍ فِي ذَلِكَ، ﴿وَتَأْكُلُونَ التُّرَاثَ﴾ يَعْنِي: الْمِيرَاثَ ﴿أَكْلا لَمًّا﴾ أَيْ: مِنْ أَيِّ جِهَةٍ حَصَلَ لَهُمْ، مِنْ حَلَالٍ أَوْ حَرَامٍ، ﴿وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا﴾ أَيْ: كَثِيرًا -زَادَ بَعْضُهُمْ: فَاحِشًا.","w":"ابن كثير","en":"\"And you do not urge one another to feed the poor\" — that is, they do not command kindness to the poor and needy, nor do they urge one another to it; \"and you consume inheritance, devouring it greedily\" — that is, from whatever source it comes to them, lawful or unlawful; \"and you love wealth with immense love\" — that is, a great deal; some added: an excessive love."}],"h":[]},{"id":"muddathir","ch":"hadd","t":"«ولم نك نطعم المسكين»: من أسباب سقر","e":"جواب أصحاب اليمين للمجرمين بأنهم لم يكونوا يطعمون المسكين.","ay":[[74,38,48]],"q":[{"bk":"saadi","s":74,"ay":44,"x":"{ولم نكُ نطعِمُ المسكينَ}: فلا إخلاص للمعبودِ ولا إحسانَ ولا نفع للخلق المحتاجين، {وكنَّا نخوضُ مع الخائضينَ}؛ أي: نخوض بالباطل ونجادل به الحقَّ، {وكنَّا نكذِّبُ بيوم الدِّينِ}: هذه آثار الخوض بالباطل، وهو التَّكذيب بالحقِّ، ومن أحقِّ الحقِّ يوم الدين، الذي هو محلُّ الجزاء على الأعمال وظهور مُلك الله وحُكمه العدل لسائر الخلق، فاستمرَّ عَمَلُنا على هذا المذهب الباطل {حتَّى أتانا اليقين}؛ أي: الموت، فلما ماتوا على الكفر؛ تعذَّرت حينئذٍ عليهم الحِيَلُ، وانسدَّ في وجوههم باب الأمل.","w":"السعدي","en":"\"And we did not used to feed the poor\": there was no sincerity toward the One worshipped, no kindness, and no benefit to needy creation; \"and we used to engage with those who engage\" — that is, to engage in falsehood and dispute with it against the truth; \"and we used to deny the Day of Judgement\" — these are the effects of engaging in falsehood, which is denying the truth, and among the most true of truths is the Day of Judgement, the place of recompense for deeds and the manifestation of Allah's sovereignty and just ruling over all creation; so our deeds went on in this false way \"until the certainty came to us\" — that is, death. When they died in disbelief, all their stratagems failed them and the door of hope was shut in their faces."},{"bk":"ibnkathir","s":74,"ay":44,"x":"يَقُولُ تَعَالَى مُخْبِرًا أَنَّ: ﴿كُلُّ نَفْسٍ بِمَا كَسَبَتْ رَهِينَةٌ﴾ أَيْ: مُعْتَقَلَةٌ بِعَمَلِهَا يَوْمَ الْقِيَامَةِ، قَالَهُ ابْنُ عَبَّاسٍ وَغَيْرُهُ: ﴿إِلا أَصْحَابَ الْيَمِينِ﴾ فَإِنَّهُمْ ﴿فِي جَنَّاتٍ يَتَسَاءَلُونَ عَنِ الْمُجْرِمِينَ﴾ أَيْ: يَسْأَلُونَ الْمُجْرِمِينَ وَهُمْ فِي الْغُرُفَاتِ وَأُولَئِكَ فِي الدِّرْكَاتِ قَائِلِينَ لَهُمْ: ﴿مَا سَلَكَكُمْ فِي سَقَرَ قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ وَلَمْ نَكُ نُطْعِمُ الْمِسْكِينَ﴾ أَيْ: مَا عَبَدَنَا رَبَّنَا وَلَا أَحْسَنَّا إِلَى خَلْقِهِ مِنْ جِنْسِنَا، ﴿وَكُنَّا نَخُوضُ مَعَ الْخَائِضِينَ﴾ أَيْ: نَتَكَلَّمُ فِيمَا لَا نَعْلَمُ.","w":"ابن كثير","en":"The Exalted says, informing that \"every soul, for what it has earned, is held in pledge\" — that is, detained by its deed on the Day of Resurrection, as Ibn Abbas and others said — \"except the companions of the right\", for they will be \"in gardens, asking one another about the criminals\" — they will ask the criminals while they are in the upper chambers and those others are in the lowest depths, saying to them: \"What put you into Saqar? They will say: We were not of those who prayed, nor did we feed the poor\" — that is, we did not worship our Lord nor did we do good to His creation of our own kind — \"and we used to engage with those who engage\" — that is, we spoke of what we did not know."}],"h":[]},{"id":"qalam","ch":"hadd","t":"أصحاب الجنة: «وغدوا على حرد قادرين»","e":"قصة أصحاب الجنة الذين أقسموا ليصرمنها مصبحين وتخافتوا ألا يدخلها عليهم مسكين.","ay":[[68,17,33]],"q":[{"bk":"saadi","s":68,"ay":25,"x":"{وغَدَوۡا}: في هذه الحالة الشنيعة والقسوة وعدم الرحمة {على حردٍ قادرينَ}؛ أي: على إمساكٍ ومنعٍ لحقِّ الله جازمين بقدرتهم عليها. {26 ـ 27}{فلمَّا رأوۡها}: على الوصف الذي ذَكَرَ الله كالصريم، {قالوا}: من الحيرة والانزعاج، {إنَّا لضالُّون}؛ أي: تائهون عنها، لعلَّها غيرها، فلما تحقَّقوها ورجعت إليهم عقولهم؛ قالوا:{بل نحن محرومون}: منها، فعرفوا حينئذٍ أنَّه عقوبةٌ.","w":"السعدي","en":"\"And they went early\" in this wicked state, with hardness of heart and lack of mercy, \"determined in their ability\" — that is, set on withholding and denying Allah's due, certain of their power over it. \"So when they saw it\" as Allah described, like a harvested field, \"they said\": in bewilderment and alarm, \"Indeed, we are lost\" — wandering away from it, perhaps it was another garden. When they made sure of it and their minds returned to them, they said: \"Rather, we are deprived\" of it; so they then knew that it was a punishment."},{"bk":"ibnkathir","s":68,"ay":24,"x":"ثُمَّ فَسَّرَ اللَّهُ عَالِمُ السِّرِّ وَالنَّجْوَى مَا كَانُوا يَتَخَافَتُونَ بِهِ، فَقَالَ: ﴿فَانْطَلَقُوا وَهُمْ يَتَخَافَتُونَ أَنْ لَا يَدْخُلَنَّهَا الْيَوْمَ عَلَيْكُمْ مِسْكِينٌ﴾ أَيْ: يَقُولُ بَعْضُهُمْ لِبَعْضٍ: لَا تُمَكِّنُوا الْيَوْمَ فَقِيرًا يَدْخُلُهَا عَلَيْكُمْ!","w":"ابن كثير","en":"Then Allah, Knower of secrets and private talk, explained what they were whispering to one another: \"So they set out, whispering among themselves, that no poor person should enter it today upon you\" — that is, each of them says to the other: do not allow any poor man to come in upon you today!"}],"h":[]},{"id":"ibrahim","ch":"dayf","t":"«هل أتاك حديث ضيف إبراهيم المكرمين»","e":"وصف ضيف إبراهيم عليه السلام بأنهم المكرمون ومجيئه إليهم بعجل سمين حنيذ.","ay":[[51,24,27],[15,51,52],[11,69,70]],"q":[{"bk":"ibnkathir","s":51,"ay":24,"x":"وَقَوْلُهُ: ﴿هَلْ أَتَاكَ حَدِيثُ ضَيْفِ إِبْرَاهِيمَ الْمُكْرَمِينَ﴾ أَيِ: الَّذِينَ أَرْصَدَ لَهُمُ الْكَرَامَةَ.","w":"ابن كثير","en":"His words: \"Has there reached you the story of the honoured guests of Ibrahim?\" — that is, those for whom honour had been prepared."},{"bk":"ibnkathir","s":51,"ay":26,"x":"وَقَوْلُهُ: ﴿فَرَاغَ إِلَى أَهْلِهِ﴾ أَيِ: انْسَلَّ خُفْيَةً فِي سُرْعَةٍ، ﴿فَجَاءَ بِعِجْلٍ سَمِينٍ﴾ أَيْ: مِنْ خِيَارِ مَالِهِ.","w":"ابن كثير","en":"His words: \"Then he slipped away to his family\" — that is, he went quietly and quickly — \"and came with a fat calf\" — that is, from the best of his wealth."},{"bk":"ibnkathir","s":11,"ay":69,"x":"﴿فَمَا لَبِثَ أَنْ جَاءَ بِعِجْلٍ حَنِيذٍ﴾ أَيْ: ذَهَبَ سَرِيعًا، فَأَتَاهُمْ بِالضِّيَافَةِ، وَهُوَ عجل: فتى البقر، حَنِيذ: [وَهُوَ] مَشْوي [شَيًّا نَاضِجًا] عَلَى الرّضْف، وَهِيَ الْحِجَارَةُ المُحْماة.","w":"ابن كثير","en":"\"And he did not delay in bringing a roasted calf\" — that is, he went quickly and brought them hospitality; and it was a calf, the young of cattle, roasted — \"hanidh\" meaning properly cooked on heated stones."}],"h":["dayf"]},{"id":"lut","ch":"dayf","t":"«إن هؤلاء ضيفي فلا تفضحون»","e":"قول لوط عليه السلام لقومه في أضيافه: «فلا تفضحون» و«ولا تخزون في ضيفي».","ay":[[15,67,71],[11,77,79]],"q":[{"bk":"saadi","s":15,"ay":68,"x":"{وجاء أهلُ المدينة}؛ أي: المدينة التي فيها لوطٌ، {يستبشرونَ}؛ أي: يبشِّر بعضُهم بعضاً بأضياف لوطٍ وصباحةِ وجوههم واقتدارهم عليهم، وذلك لقصدِهِم فعلَ الفاحشة فيهم، فجاؤوا حتى وصلوا إلى بيت لوطٍ، فجعلوا يعالجون لوطاً على أضيافه، ولوطٌ يستعيذُ منهم ويقولُ:{إنَّ هؤلاء ضَيۡفي فلا تَفۡضَحونِ.","w":"السعدي","en":"\"And the people of the city came\" — the city in which Lut was — \"rejoicing at the news\", each giving the other news of Lut's guests and their handsome faces and their being within reach, intending to commit the indecency with them. They came until they reached Lut's house and began to press Lut about his guests, while Lut sought refuge from them and said: \"Indeed, these are my guests, so do not disgrace me.\""},{"bk":"ibnkathir","s":11,"ay":78,"x":"وَقَوْلُهُ: ﴿فَاتَّقُوا اللَّهَ وَلا تُخْزُونِ فِي ضَيْفِي﴾ أَيْ: اقْبَلُوا مَا آمُرُكُمْ بِهِ مِنَ الِاقْتِصَارِ عَلَى نِسَائِكُمْ ، ﴿أَلَيْسَ مِنْكُمْ رَجُلٌ رَشِيدٌ﴾ أَيْ: [لَيْسَ مِنْكُمْ رَجُلٌ] فِيهِ خَيْرٌ، يَقْبَلُ مَا آمره به، ويترك ما أنهاه عَنْهُ؟","w":"ابن كثير","en":"His words: \"So fear Allah and do not disgrace me concerning my guests\" — that is, accept what I command you of confining yourselves to your wives — \"Is there not among you a man of sound judgement?\" — that is, is there not among you a man with good in him who will accept what I command him and leave what I forbid him?"}],"h":[]},{"id":"khidr","ch":"dayf","t":"«استطعما أهلها فأبوا أن يضيفوهما»","e":"خبر القرية التي استطعمها موسى والخضر عليهما السلام فأبوا أن يضيّفوهما.","ay":[[18,77,77]],"q":[{"bk":"saadi","s":18,"ay":77,"x":"{فانطلقا حتى إذا أتيا أهل قريةٍ استطعما أهلها}؛ أي: استضافاهم فلم يُضَيِّفوهُما …","w":"السعدي","en":"\"So they set out until, when they came to the people of a town, they asked its people for food\" — that is, they asked them to host them, but they did not host them …"}],"h":[]},{"id":"yusuf","ch":"dayf","t":"«ألا ترون أني أوفي الكيل وأنا خير المنزلين»","e":"قول يوسف عليه السلام لإخوته: «وأنا خير المنزلين».","ay":[[12,59,59]],"q":[{"bk":"saadi","s":12,"ay":59,"x":"{ولما جهَّزهم بجهَازهم}؛ أي: كال لهم كما كان يَكيلُ لغيرِهم، وكان من تدبيرِهِ الحسن أنَّه لا يَكيل لكلِّ واحدٍ أكثر من حِمْل بعير، وكان قد سألهم عن حالهم، فأخبروه أنَّ لهم أخاً عند أبيه، وهو بنيامين، فقال لهم:{ائتوني بأخٍ لكم من أبيكم}: ثم رغَّبهم في الإتيان به، فقال:{ألا تَرَوۡنَ أنِّي أوفي الكيلَ وأنا خيرُ المنزِلين}: في الضيافة والإكرام.","w":"السعدي","en":"\"And when he had furnished them with their supplies\" — that is, he measured out for them as he measured for others, and part of his fine management was that he did not measure for anyone more than a camel's load. He had asked them about their condition and they told him they had a brother with their father, Binyamin, so he said to them: \"Bring me a brother of yours from your father.\" Then he encouraged them to bring him, saying: \"Do you not see that I give full measure and that I am the best of hosts\" — in hospitality and honour."}],"h":["abutalha"]},{"id":"sabil","ch":"dayf","t":"«وآت ذا القربى حقه والمسكين وابن السبيل»","e":"ذكر ابن السبيل مع ذي القربى والمسكين في الأمر بإيتاء الحق.","ay":[[17,26,26],[4,36,36],[30,38,38]],"q":[{"bk":"saadi","s":17,"ay":26,"x":"يقول تعالى: {وآت ذا القُربى حقَّه}: من البرِّ والإكرام الواجب والمسنون، وذلك الحقُّ يتفاوت بتفاوت الأحوال والأقارب والحاجة وعدمها والأزمنة، {والمسكينَ}: آته حقَّه من الزَّكاة ومن غيرها؛ لتزول مسكنتُه، {وابنَ السبيل}: وهو الغريب المنقطع به عن بلده، فيُعْطى الجميع من المال، على وجهٍ لا يضرُّ المعطي، ولا يكون زائداً على المقدار اللائق؛ فإنَّ ذلك تبذيرٌ، قد نهى الله عنه وأخبر: إنَّ المبذِّرين {إخوانُ الشياطين}: لأنَّ الشيطان لا يدعو إلاَّ إلى كلِّ خَصلة ذميمةٍ، فيدعو الإنسان إلى البخل والإمساك؛ فإذا عصاه؛ دعاه إلى الإسراف والتبذير، والله تعالى إنَّما يأمُرُ بأعدل الأمور وأقسطِها، ويمدحُ عليه؛ كما في قوله عن عباد الرحمن الأبرار:{والذين إذا أنفقوا لم يُسۡرِفوا ولم يَقۡتُروا وكان بين ذلك قَواماً}.","w":"السعدي","en":"The Exalted says: \"And give the relative his right\" — of kindness and honour, obligatory and recommended, and that right varies with circumstances, kinsmen, need or its absence, and times — \"and the poor\" — give him his right from zakat and other than it, so that his poverty goes away — \"and the wayfarer\" — the stranger cut off from his land. All are given from wealth in a way that does not harm the giver and does not exceed the fitting measure, for that is squandering, which Allah forbade, informing that the squanderers are \"brothers of the devils\", because the devil calls only to every blameworthy trait; he calls a person to miserliness and withholding, and if he disobeys him, he calls him to extravagance and squandering. Allah only commands the most just and balanced of matters and praises it, as in His words about the servants of the Most Merciful, the righteous: \"And those who, when they spend, are neither extravagant nor stingy, but are ever between that a medium.\""},{"bk":"saadi","s":4,"ay":36,"x":"وهو الغريب الذي احتاج في بلد الغربة أو لم يحتج؛ فله حقٌّ على المسلمين لشدَّة حاجتِهِ وكونِهِ في غير وطنه بتبليغه إلى مقصوده أو بعض مقصوده وبإكرامه وتأنيسه.","w":"السعدي","en":"He is the stranger, whether he needs help in a foreign land or does not; he has a right over Muslims because of his great need and being outside his homeland, by conveying him to his destination or part of it, and by honouring him and putting him at ease."}],"h":["haqq"]},{"id":"adabbayt","ch":"dayf","t":"«ليس عليكم جناح أن تأكلوا من بيوتكم أو بيوت آبائكم»","e":"رفع الحرج في الأكل من بيوت الأقارب والأصدقاء، جميعاً أو أشتاتاً.","ay":[[24,61,61]],"q":[{"bk":"saadi","s":24,"ay":61,"x":"وفيها: دليلٌ على أن المتصرِّفَ في بيت الإنسان كزوجتِهِ وأختِهِ ونحوِهما يجوزُ لهما الأكل عادةً وإطعامُ السائل المعتاد.","w":"السعدي","en":"And in it is evidence that one who manages a person's home, such as his wife, his sister and the like, may eat as is customary and may feed the usual beggar."},{"bk":"saadi","s":24,"ay":61,"x":"وفيها: دليلٌ على جوازِ المشاركة في الطعام، سواء أكلوا مجتمعينَ أو متفرِّقين، ولو أفضى ذلك إلى أن يأكُلَ بعضُهم أكثر من بعض.","w":"السعدي","en":"And in it is evidence that sharing in food is permitted, whether they eat together or separately, even if that leads some of them to eat more than others."}],"h":[]},{"id":"walima","ch":"dayf","t":"«لا تدخلوا بيوت النبي إلا أن يؤذن لكم إلى طعام»","e":"أدب دخول بيوت النبي ﷺ لطعام، وعدم انتظار نضجه، والانصراف بعد الأكل.","ay":[[33,53,53]],"q":[{"bk":"saadi","s":33,"ay":53,"x":"يأمر تعالى عبادَه المؤمنين بالتأدُّب مع رسول الله - صلى الله عليه وسلم - في دخول بيوتِهِ، فقال:{يا أيُّها الذين آمنوا لا تدخُلوا بيوت النبيِّ إلاَّ أن يُؤۡذَنَ لكم إلى طعام}؛ أي: لا تدخُلوها بغير إذنٍ للدخول فيها لأجل الطعام، وأيضاً لا تكونوا {ناظرينَ إناه}؛ أي: منتظرين ومتأنين لانتظار نضجه أو سعة صدرٍ بعد الفراغ منه.","w":"السعدي","en":"The Exalted commands His believing servants to show good manners with the Messenger of Allah ﷺ in entering his houses, saying: \"O you who have believed, do not enter the houses of the Prophet unless you are permitted for a meal\" — that is, do not enter without permission to enter for the sake of a meal, and also do not be \"waiting for its readiness\" — that is, waiting for it to be cooked or lingering after finishing it."}],"h":["walima"]},{"id":"yamin","ch":"ahkam","t":"كفارة اليمين: «إطعام عشرة مساكين من أوسط ما تطعمون أهليكم»","e":"جعل إطعام عشرة مساكين أحد خصال كفارة اليمين.","ay":[[5,89,89]],"q":[{"bk":"saadi","s":5,"ay":89,"x":"أي: في أيمانكم التي صدرت على وجه اللغو، وهي الأيمان التي حلف بها المقسم من غير نيَّة ولا قصدٍ، أو عقدها يظنُّ صدقَ نفسه، فبان بخلاف ذلك، {ولكن يؤاخذكم بما عقَّدتم الأيمان}؛ أي: بما عزمتم عليه وعقدت عليه قلوبكم؛ كما قال في الآية الأخرى:{ولكن يؤاخِذُكُم بما كَسَبَتۡ قلوبُكم}، {فكفَّارتُهُ}؛ أي: كفارة اليمين الذي عقدتموها بقصدكم: {إطعام عشرة مساكين}، وذلك الإطعام {من أوسط ما تُطۡعِمون أهليكم أو كسوتهم}؛ أي: كسوة عشرة مساكين، والكسوة هي التي تجزي في الصلاة، {أو تحرير رقبة}؛ [أي: عتق رقبة] مؤمنةٍ؛ كما قُيِّدت في غير هذا الموضع؛ فمتى فعل واحداً من هذه الثلاثة؛ فقد انحلَّت يمينه.","w":"السعدي","en":"\"Allah does not impose blame on you for what is unintentional in your oaths\" — those oaths a person swears without intention or purpose, or swears thinking himself truthful and it turns out otherwise — \"but He imposes blame for what you contracted by oath\" — that is, what you resolved and your hearts bound — \"so its expiation is\" — the expiation of the oath you made deliberately — \"the feeding of ten poor persons\", and that feeding is \"from the average of that which you feed your families, or their clothing\" — that is, clothing for ten poor persons, and the clothing is what suffices for prayer — \"or the freeing of a slave\" who is a believer, as is restricted elsewhere. When he does one of these three, his oath is dissolved."},{"bk":"ibnkathir","s":5,"ay":89,"x":"وَقَوْلُهُ: ﴿مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ﴾ قَالَ ابْنُ عَبَّاسٍ، وَسَعِيدُ بْنُ جُبَيْرٍ، وَعِكْرِمَةُ: أَيْ مِنْ أَعْدَلِ مَا تُطْعِمُونَ أَهْلِيكُمْ.","w":"ابن كثير","en":"His words: \"from the average of that which you feed your families\" — Ibn Abbas, Sa'id ibn Jubayr and Ikrimah said: that is, from the most moderate of what you feed your families."}],"h":[]},{"id":"zihar","ch":"ahkam","t":"كفارة الظهار: «فإطعام ستين مسكيناً»","e":"إطعام ستين مسكيناً خصلةً في كفارة الظهار لمن لم يستطع الصيام.","ay":[[58,3,4]],"q":[{"bk":"saadi","s":58,"ay":4,"x":"{فمن لم يجِدۡ}: رقبةً يُعْتِقُها؛ بأن لم يجِدْها أو لم يجِدْ ثَمَنَها، {فـ} عليه {صيامُ شهرين متتابعين من قبل أن يَتَماسَّا فمَن لمۡ يَسۡتَطِعۡ}: الصيام، {فإطعامُ ستينَ مسكيناً}: إمَّا أنْ يطعِمَهم من قوت بلده ما يكفيهم؛ كما هو قول كثيرٍ من المفسِّرين، وإمَّا أنْ يطعِمَ كلَّ مسكين مُدَّ بُرٍّ أو نصفَ صاع من غيره مما يُجْزِي في الفطرة؛ كما هو قول طائفة أخرى.","w":"السعدي","en":"\"But whoever does not find\" a slave to free, either because he does not find one or does not find its price, \"then\" he must fast \"two months consecutively before they touch one another; and whoever is not able\" to fast \"then the feeding of sixty poor persons\": either he feeds them from the staple of his land what suffices them, as many of the exegetes say, or he feeds each poor person a mudd of wheat or half a sa' of other than it of what suffices in the zakat of breaking the fast, as another group says."}],"h":[]},{"id":"hady","ch":"ahkam","t":"«فكلوا منها وأطعموا البائس الفقير»","e":"الأمر بالأكل من الهدي وإطعام البائس الفقير والقانع والمعتر.","ay":[[22,28,28],[22,36,36]],"q":[{"bk":"saadi","s":22,"ay":28,"x":"وهذا من المنافع الدينيَّة والدنيويَّة؛ أي: ليذكروا اسم الله عند ذبح الهدايا شكراً لله على ما رَزَقَهم منها ويسَّرها لهم؛ فإذا ذبحتموها؛ {فكلوا منها وأطعموا البائسَ الفقير}؛ أي: شديد الفقر.","w":"السعدي","en":"And this is among the religious and worldly benefits: that is, that they mention the name of Allah over the slaughter of the sacrificial animals in thanks to Allah for what He provided them of them and made easy for them; so when you have slaughtered them, \"then eat from them and feed the desperately poor\" — severely poor."},{"bk":"saadi","s":22,"ay":36,"x":"أي: سقطت في الأرض جُنوبها حين تُسلخ ثم يسقِطُ الجزارُ جنوبَها على الأرض؛ فحينئذٍ قد استعدَّتْ لأن يُؤْكَلَ منها؛ {فكلوا منها}: وهذا خطابٌ للمهدي، فيجوز له الأكل من هديِهِ، {وأطعِموا القانعَ والمعتَرَّ}؛ أي: الفقير الذي لا يسأل تقنُّعاً وتعففاً، والفقير الذي يسألُ؛ فكلٌّ منهما له حقٌّ فيهما.","w":"السعدي","en":"That is, their sides fall to the ground when they are skinned and the butcher lays their sides on the ground; at that point they are ready to be eaten from: \"so eat from them\" — this addresses the one who presented the offering, so he may eat from his offering — \"and feed the one who is content and the one who asks\" — the poor who does not ask out of self-restraint and modesty, and the poor who does ask; each of the two has a right in them."}],"h":["budn"]},{"id":"siyam","ch":"siyam","t":"«يا أيها الذين آمنوا كتب عليكم الصيام لعلكم تتقون»","e":"فرض الصيام وحكمته، وفيها ترك الأكل والشرب، ومواساة الفقراء.","ay":[[2,183,185]],"q":[{"bk":"saadi","s":2,"ay":183,"x":"ثم ذكر تعالى حكمته في مشروعية الصيام فقال:{لعلكم تتقون}؛ فإن الصيام من أكبر أسباب التقوى لأن فيه امتثال أمر الله واجتناب نهيه، فممِّا اشتمل عليه من التقوى أن الصائم يترك ما حرم الله عليه من الأكل والشرب والجماع ونحوها التي تميل إليها نفسه متقرباً بذلك إلى الله راجياً بتركها ثوابه، فهذا من التقوى، ومنها: أن الصائم يدرب نفسه على مراقبة الله تعالى فيترك ما تهوى نفسه مع قدرته عليه لعلمه باطلاع الله عليه، ومنها: أنَّ الصيام يضيق مجاري الشيطان فإنه يجري من ابن ادم مجرى الدم فبالصيام يضعف نفوذه وتقل منه المعاصي، ومنها: أن الصائم في الغالب تكثر طاعته والطاعات من خصال التقوى، ومنها: أن الغني إذا ذاق ألم الجوع أوجب له ذلك مواساة الفقراء المعدمين.","w":"السعدي","en":"Then He mentioned the wisdom in prescribing fasting, saying: \"that you may become righteous\". Fasting is one of the greatest causes of taqwa, because in it is complying with Allah's command and avoiding His prohibition. Among the taqwa it includes: that the fasting person leaves what Allah forbade him of eating, drinking, intercourse and the like, which his soul inclines to, drawing near to Allah by that and hoping for His reward by leaving it; and that is taqwa. Among them: the fasting person trains his soul in awareness of Allah, leaving what his soul desires though able to have it, knowing that Allah is aware of him. Among them: that fasting narrows the channels of the devil, who runs in the son of Adam like blood, so by fasting his reach weakens and sins lessen. Among them: that the fasting person generally increases in obedience, and acts of obedience are among the traits of taqwa. And among them: that the rich person, when he tastes the pain of hunger, is moved to share with the destitute poor."}],"h":["farha"]},{"id":"fidya","ch":"siyam","t":"«وعلى الذين يطيقونه فدية طعام مسكين»","e":"فدية طعام مسكين عن الصيام في آية الصيام.","ay":[[2,184,184]],"q":[{"bk":"saadi","s":2,"ay":184,"x":"وقوله:{وعلى الذين يطيقونه}؛ أي: يطيقون الصيام {فدية}؛ عن كل يوم يفطرونه {طعام مسكين}؛ وهذا في ابتداء فرض الصيام لما كانوا غير معتادين للصيام وكان فرضه حتماً فيه مشقة عليهم دَرَّجَهم الربُّ الحكيم بأسهل طريق، وخَيَّرَ المطيق للصوم بين أن يصوم وهو أفضل أو يطعم ولهذا قال:{وأن تصوموا خير لكم}؛ ثم بعد ذلك جعل الصيام حتماً على المطيق، وغير المطيق يفطر ويقضيه في أيام أُخَر، وقيل: وعلى الذين يطيقون؛ أي يتكلفونه، ويشق عليهم مشقة غير محتملة كالشيخ الكبير، فدية عن كل يوم مسكين، وهذا هو الصحيح.","w":"السعدي","en":"His words: \"And upon those who are able to do it — a ransom: the feeding of a poor person\" — that is, those able to fast owe a ransom for each day they break, the feeding of a poor person. This was at the beginning of the prescription of fasting, when they were not accustomed to it and its being strictly obligatory was hard on them, so the wise Lord brought them along by the easiest way and gave the one able to fast a choice between fasting, which is better, or feeding; hence He said: \"and that you fast is better for you\". Then after that He made fasting strictly obligatory for the one able, while the one unable breaks the fast and makes it up on other days. And it is said: \"and upon those who are able to do it\" means: who burden themselves with it, and it is exceedingly hard for them, like the very old man, a ransom for each day, a poor person; and this is the sound view."},{"bk":"ibnkathir","s":2,"ay":184,"x":"وَأَمَّا الصَّحِيحُ الْمُقِيمُ الذِي يُطيق الصِّيَامَ، فَقَدْ كَانَ مخيَّرًا بَيْنَ الصِّيَامِ وَبَيْنَ الْإِطْعَامِ، إِنْ شَاءَ صَامَ، وَإِنْ شَاءَ أَفْطَرَ، وَأَطْعَمَ عَنْ كُلِّ يَوْمٍ مِسْكِينًا، فَإِنْ أَطْعَمَ أَكْثَرَ مِنْ مِسْكِينٍ عَنْ كُلِّ يَوْمٍ، فَهُوَ خَيْرٌ، وَإِنْ صَامَ فَهُوَ أَفْضَلُ مِنَ الْإِطْعَامِ، قَالَهُ ابْنُ مَسْعُودٍ، وَابْنُ عَبَّاسٍ، وَمُجَاهِدٌ، وَطَاوُسٌ، وَمُقَاتِلُ بْنُ حَيَّانَ، وَغَيْرُهُمْ مِنَ السَّلَفِ؛ وَلِهَذَا قَالَ تَعَالَى: ﴿وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ فَمَنْ تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَهُ وَأَنْ تَصُومُوا خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ …","w":"ابن كثير","en":"As for the healthy resident who is able to fast, he was given a choice between fasting and feeding: if he wished he fasted, and if he wished he broke the fast and fed a poor person for each day; and if he fed more than one poor person for a day, that was better, and if he fasted that was better than feeding. This was said by Ibn Mas'ud, Ibn Abbas, Mujahid, Tawus, Muqatil ibn Hayyan and others of the early generations; that is why the Exalted said: \"And upon those who are able to do it — a ransom: the feeding of a poor person. And whoever volunteers good, it is better for him; and that you fast is better for you, if you only knew\" …"}],"h":[]},{"id":"sahur","ch":"siyam","t":"«وكلوا واشربوا حتى يتبين لكم الخيط الأبيض من الخيط الأسود»","e":"إباحة الأكل والشرب حتى تبيّن الفجر ثم إتمام الصيام إلى الليل.","ay":[[2,187,187]],"q":[{"bk":"saadi","s":2,"ay":187,"x":"هذا غاية للأكل والشرب والجماع، وفيه أنه إذا أكل ونحوه شاكًّا في طلوع الفجر فلا بأس عليه، وفيه دليل على استحباب السحور للأمر، وأنه يستحب تأخيره، أخذاً من معنى رخصة الله وتسهيله على العباد، وفيه أيضاً دليل على أنه يجوز أن يدركه الفجر وهو جنب من الجماع قبل أن يغتسل، ويصح صيامه لأن لازم إباحة الجماع إلى طلوع الفجر، أن يدركه الفجر وهو جنب، ولازم الحق حق {ثم}؛ إذا طلع الفجر {أتموا الصيام}؛ أي: الإمساك عن المفطرات {إلى الليل}؛ وهو غروب الشمس، ولما كان إباحة الوطء في ليالي الصيام ليست إباحة عامة لكل أحد، فإن المعتكف لا يحل له ذلك استثناه بقوله:{ولا تباشروهن وأنتم عاكفون في المساجد}؛ أي: وأنتم متصفون بذلك.","w":"السعدي","en":"This is the limit for eating, drinking and intercourse. In it is that if a person eats or the like while doubtful about the dawn, there is no blame on him; and in it is evidence that the pre-dawn meal is recommended because of the command, and that it is recommended to delay it, taken from the meaning of Allah's concession and ease for servants. In it is also evidence that dawn may overtake a person in a state of major impurity from intercourse before he washes, and his fast is valid, since permission of intercourse until dawn necessarily means dawn may find him in that state, and what follows the right is right. \"Then\", once dawn rises, \"complete the fast\" — that is, abstaining from what breaks it — \"until the night\", which is sunset. And since permission of intercourse on the nights of fasting is not general for everyone, the one in seclusion in the mosque is not permitted it, He excepted him by His words: \"And do not have relations with them while you are in seclusion in the mosques\" — that is, while you are in that state."}],"h":["tasahharu","ajjalu"]}],"ay":{"189":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ","190":"أَيَّامٗا مَّعۡدُودَٰتٖۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدۡيَةٞ طَعَامُ مِسۡكِينٖۖ فَمَن تَطَوَّعَ خَيۡرٗا فَهُوَ خَيۡرٞ لَّهُۥۚ وَأَن تَصُومُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","191":"شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدٗى لِّلنَّاسِ وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ","193":"أُحِلَّ لَكُمۡ لَيۡلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمۡۚ هُنَّ لِبَاسٞ لَّكُمۡ وَأَنتُمۡ لِبَاسٞ لَّهُنَّۗ عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ أَنفُسَكُمۡ فَتَابَ عَلَيۡكُمۡ وَعَفَا عَنكُمۡۖ فَٱلۡـَٰٔنَ بَٰشِرُوهُنَّ وَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ وَكُلُواْ وَٱشۡرَبُواْ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلۡخَيۡطُ ٱلۡأَبۡيَضُ مِنَ ٱلۡخَيۡطِ ٱلۡأَسۡوَدِ مِنَ ٱلۡفَجۡرِۖ ثُمَّ أَتِمُّواْ ٱلصِّيَامَ إِلَى ٱلَّيۡلِۚ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمۡ عَٰكِفُونَ فِي ٱلۡمَسَٰجِدِۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَقۡرَبُوهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَّقُونَ","221":"يَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلۡ مَآ أَنفَقۡتُم مِّنۡ خَيۡرٖ فَلِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ","500":"وَإِذَا حَضَرَ ٱلۡقِسۡمَةَ أُوْلُواْ ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينُ فَٱرۡزُقُوهُم مِّنۡهُ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا","528":"۞ وَٱعۡبُدُواْ ٱللَّهَ وَلَا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗا وَبِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱلۡجَارِ ذِي ٱلۡقُرۡبَىٰ وَٱلۡجَارِ ٱلۡجُنُبِ وَٱلصَّاحِبِ بِٱلۡجَنۢبِ وَٱبۡنِ ٱلسَّبِيلِ وَمَا مَلَكَتۡ أَيۡمَٰنُكُمۡۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخۡتَالٗا فَخُورًا","757":"لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلۡأَيۡمَٰنَۖ فَكَفَّٰرَتُهُۥٓ إِطۡعَامُ عَشَرَةِ مَسَٰكِينَ مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِيكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِيرُ رَقَبَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖۚ ذَٰلِكَ كَفَّٰرَةُ أَيۡمَٰنِكُمۡ إِذَا حَلَفۡتُمۡۚ وَٱحۡفَظُوٓاْ أَيۡمَٰنَكُمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَشۡكُرُونَ","802":"قُلۡ أَغَيۡرَ ٱللَّهِ أَتَّخِذُ وَلِيّٗا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَهُوَ يُطۡعِمُ وَلَا يُطۡعَمُۗ قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَكُونَ أَوَّلَ مَنۡ أَسۡلَمَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ","1541":"وَلَقَدۡ جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞۖ فَمَا لَبِثَ أَن جَآءَ بِعِجۡلٍ حَنِيذٖ","1542":"فَلَمَّا رَءَآ أَيۡدِيَهُمۡ لَا تَصِلُ إِلَيۡهِ نَكِرَهُمۡ وَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۚ قَالُواْ لَا تَخَفۡ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمِ لُوطٖ","1549":"وَلَمَّا جَآءَتۡ رُسُلُنَا لُوطٗا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعٗا وَقَالَ هَٰذَا يَوۡمٌ عَصِيبٞ","1550":"وَجَآءَهُۥ قَوۡمُهُۥ يُهۡرَعُونَ إِلَيۡهِ وَمِن قَبۡلُ كَانُواْ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِۚ قَالَ يَٰقَوۡمِ هَٰٓؤُلَآءِ بَنَاتِي هُنَّ أَطۡهَرُ لَكُمۡۖ فَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ فِي ضَيۡفِيٓۖ أَلَيۡسَ مِنكُمۡ رَجُلٞ رَّشِيدٞ","1551":"قَالُواْ لَقَدۡ عَلِمۡتَ مَا لَنَا فِي بَنَاتِكَ مِنۡ حَقّٖ وَإِنَّكَ لَتَعۡلَمُ مَا نُرِيدُ","1654":"وَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ قَالَ ٱئۡتُونِي بِأَخٖ لَّكُم مِّنۡ أَبِيكُمۡۚ أَلَا تَرَوۡنَ أَنِّيٓ أُوفِي ٱلۡكَيۡلَ وَأَنَا۠ خَيۡرُ ٱلۡمُنزِلِينَ","1852":"وَنَبِّئۡهُمۡ عَن ضَيۡفِ إِبۡرَٰهِيمَ","1853":"إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمٗا قَالَ إِنَّا مِنكُمۡ وَجِلُونَ","1868":"وَجَآءَ أَهۡلُ ٱلۡمَدِينَةِ يَسۡتَبۡشِرُونَ","1869":"قَالَ إِنَّ هَٰٓؤُلَآءِ ضَيۡفِي فَلَا تَفۡضَحُونِ","1870":"وَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ","1871":"قَالُوٓاْ أَوَلَمۡ نَنۡهَكَ عَنِ ٱلۡعَٰلَمِينَ","1872":"قَالَ هَٰٓؤُلَآءِ بَنَاتِيٓ إِن كُنتُمۡ فَٰعِلِينَ","2054":"وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَلَا تُبَذِّرۡ تَبۡذِيرًا","2216":"فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهۡلَ قَرۡيَةٍ ٱسۡتَطۡعَمَآ أَهۡلَهَا فَأَبَوۡاْ أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارٗا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥۖ قَالَ لَوۡ شِئۡتَ لَتَّخَذۡتَ عَلَيۡهِ أَجۡرٗا","2622":"لِّيَشۡهَدُواْ مَنَٰفِعَ لَهُمۡ وَيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ فِيٓ أَيَّامٖ مَّعۡلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۖ فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡبَآئِسَ ٱلۡفَقِيرَ","2630":"وَٱلۡبُدۡنَ جَعَلۡنَٰهَا لَكُم مِّن شَعَٰٓئِرِ ٱللَّهِ لَكُمۡ فِيهَا خَيۡرٞۖ فَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهَا صَوَآفَّۖ فَإِذَا وَجَبَتۡ جُنُوبُهَا فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡقَانِعَ وَٱلۡمُعۡتَرَّۚ كَذَٰلِكَ سَخَّرۡنَٰهَا لَكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ","2851":"لَّيۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجٞ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجٞ وَلَا عَلَى ٱلۡمَرِيضِ حَرَجٞ وَلَا عَلَىٰٓ أَنفُسِكُمۡ أَن تَأۡكُلُواْ مِنۢ بُيُوتِكُمۡ أَوۡ بُيُوتِ ءَابَآئِكُمۡ أَوۡ بُيُوتِ أُمَّهَٰتِكُمۡ أَوۡ بُيُوتِ إِخۡوَٰنِكُمۡ أَوۡ بُيُوتِ أَخَوَٰتِكُمۡ أَوۡ بُيُوتِ أَعۡمَٰمِكُمۡ أَوۡ بُيُوتِ عَمَّٰتِكُمۡ أَوۡ بُيُوتِ أَخۡوَٰلِكُمۡ أَوۡ بُيُوتِ خَٰلَٰتِكُمۡ أَوۡ مَا مَلَكۡتُم مَّفَاتِحَهُۥٓ أَوۡ صَدِيقِكُمۡۚ لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَأۡكُلُواْ جَمِيعًا أَوۡ أَشۡتَاتٗاۚ فَإِذَا دَخَلۡتُم بُيُوتٗا فَسَلِّمُواْ عَلَىٰٓ أَنفُسِكُمۡ تَحِيَّةٗ مِّنۡ عِندِ ٱللَّهِ مُبَٰرَكَةٗ طَيِّبَةٗۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ","3446":"فَـَٔاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِۚ ذَٰلِكَ خَيۡرٞ لِّلَّذِينَ يُرِيدُونَ وَجۡهَ ٱللَّهِۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","3585":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتَ ٱلنَّبِيِّ إِلَّآ أَن يُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَيۡرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنۡ إِذَا دُعِيتُمۡ فَٱدۡخُلُواْ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُواْ وَلَا مُسۡتَـٔۡنِسِينَ لِحَدِيثٍۚ إِنَّ ذَٰلِكُمۡ كَانَ يُؤۡذِي ٱلنَّبِيَّ فَيَسۡتَحۡيِۦ مِنكُمۡۖ وَٱللَّهُ لَا يَسۡتَحۡيِۦ مِنَ ٱلۡحَقِّۚ وَإِذَا سَأَلۡتُمُوهُنَّ مَتَٰعٗا فَسۡـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٖۚ ذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ وَمَا كَانَ لَكُمۡ أَن تُؤۡذُواْ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓاْ أَزۡوَٰجَهُۥ مِنۢ بَعۡدِهِۦٓ أَبَدًاۚ إِنَّ ذَٰلِكُمۡ كَانَ عِندَ ٱللَّهِ عَظِيمًا","4698":"هَلۡ أَتَىٰكَ حَدِيثُ ضَيۡفِ إِبۡرَٰهِيمَ ٱلۡمُكۡرَمِينَ","4699":"إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞ قَوۡمٞ مُّنكَرُونَ","4700":"فَرَاغَ إِلَىٰٓ أَهۡلِهِۦ فَجَآءَ بِعِجۡلٖ سَمِينٖ","4701":"فَقَرَّبَهُۥٓ إِلَيۡهِمۡ قَالَ أَلَا تَأۡكُلُونَ","4730":"وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ","4731":"مَآ أُرِيدُ مِنۡهُم مِّن رِّزۡقٖ وَمَآ أُرِيدُ أَن يُطۡعِمُونِ","4732":"إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلۡقُوَّةِ ٱلۡمَتِينُ","5106":"وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمۡ ثُمَّ يَعُودُونَ لِمَا قَالُواْ فَتَحۡرِيرُ رَقَبَةٖ مِّن قَبۡلِ أَن يَتَمَآسَّاۚ ذَٰلِكُمۡ تُوعَظُونَ بِهِۦۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ","5107":"فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ مِن قَبۡلِ أَن يَتَمَآسَّاۖ فَمَن لَّمۡ يَسۡتَطِعۡ فَإِطۡعَامُ سِتِّينَ مِسۡكِينٗاۚ ذَٰلِكَ لِتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦۚ وَتِلۡكَ حُدُودُ ٱللَّهِۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٌ","5287":"إِنَّا بَلَوۡنَٰهُمۡ كَمَا بَلَوۡنَآ أَصۡحَٰبَ ٱلۡجَنَّةِ إِذۡ أَقۡسَمُواْ لَيَصۡرِمُنَّهَا مُصۡبِحِينَ","5288":"وَلَا يَسۡتَثۡنُونَ","5289":"فَطَافَ عَلَيۡهَا طَآئِفٞ مِّن رَّبِّكَ وَهُمۡ نَآئِمُونَ","5290":"فَأَصۡبَحَتۡ كَٱلصَّرِيمِ","5291":"فَتَنَادَوۡاْ مُصۡبِحِينَ","5292":"أَنِ ٱغۡدُواْ عَلَىٰ حَرۡثِكُمۡ إِن كُنتُمۡ صَٰرِمِينَ","5293":"فَٱنطَلَقُواْ وَهُمۡ يَتَخَٰفَتُونَ","5294":"أَن لَّا يَدۡخُلَنَّهَا ٱلۡيَوۡمَ عَلَيۡكُم مِّسۡكِينٞ","5295":"وَغَدَوۡاْ عَلَىٰ حَرۡدٖ قَٰدِرِينَ","5296":"فَلَمَّا رَأَوۡهَا قَالُوٓاْ إِنَّا لَضَآلُّونَ","5297":"بَلۡ نَحۡنُ مَحۡرُومُونَ","5298":"قَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل لَّكُمۡ لَوۡلَا تُسَبِّحُونَ","5299":"قَالُواْ سُبۡحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ","5300":"فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَلَٰوَمُونَ","5301":"قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا طَٰغِينَ","5302":"عَسَىٰ رَبُّنَآ أَن يُبۡدِلَنَا خَيۡرٗا مِّنۡهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ","5303":"كَذَٰلِكَ ٱلۡعَذَابُۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ","5347":"وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِشِمَالِهِۦ فَيَقُولُ يَٰلَيۡتَنِي لَمۡ أُوتَ كِتَٰبِيَهۡ","5348":"وَلَمۡ أَدۡرِ مَا حِسَابِيَهۡ","5349":"يَٰلَيۡتَهَا كَانَتِ ٱلۡقَاضِيَةَ","5350":"مَآ أَغۡنَىٰ عَنِّي مَالِيَهۡۜ","5351":"هَلَكَ عَنِّي سُلۡطَٰنِيَهۡ","5352":"خُذُوهُ فَغُلُّوهُ","5353":"ثُمَّ ٱلۡجَحِيمَ صَلُّوهُ","5354":"ثُمَّ فِي سِلۡسِلَةٖ ذَرۡعُهَا سَبۡعُونَ ذِرَاعٗا فَٱسۡلُكُوهُ","5355":"إِنَّهُۥ كَانَ لَا يُؤۡمِنُ بِٱللَّهِ ٱلۡعَظِيمِ","5356":"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","5357":"فَلَيۡسَ لَهُ ٱلۡيَوۡمَ هَٰهُنَا حَمِيمٞ","5358":"وَلَا طَعَامٌ إِلَّا مِنۡ غِسۡلِينٖ","5359":"لَّا يَأۡكُلُهُۥٓ إِلَّا ٱلۡخَٰطِـُٔونَ","5532":"كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡ رَهِينَةٌ","5533":"إِلَّآ أَصۡحَٰبَ ٱلۡيَمِينِ","5534":"فِي جَنَّٰتٖ يَتَسَآءَلُونَ","5535":"عَنِ ٱلۡمُجۡرِمِينَ","5536":"مَا سَلَكَكُمۡ فِي سَقَرَ","5537":"قَالُواْ لَمۡ نَكُ مِنَ ٱلۡمُصَلِّينَ","5538":"وَلَمۡ نَكُ نُطۡعِمُ ٱلۡمِسۡكِينَ","5539":"وَكُنَّا نَخُوضُ مَعَ ٱلۡخَآئِضِينَ","5540":"وَكُنَّا نُكَذِّبُ بِيَوۡمِ ٱلدِّينِ","5541":"حَتَّىٰٓ أَتَىٰنَا ٱلۡيَقِينُ","5542":"فَمَا تَنفَعُهُمۡ شَفَٰعَةُ ٱلشَّٰفِعِينَ","5595":"إِنَّ ٱلۡأَبۡرَارَ يَشۡرَبُونَ مِن كَأۡسٖ كَانَ مِزَاجُهَا كَافُورًا","5596":"عَيۡنٗا يَشۡرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفۡجِيرٗا","5597":"يُوفُونَ بِٱلنَّذۡرِ وَيَخَافُونَ يَوۡمٗا كَانَ شَرُّهُۥ مُسۡتَطِيرٗا","5598":"وَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِينٗا وَيَتِيمٗا وَأَسِيرًا","5599":"إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءٗ وَلَا شُكُورًا","5600":"إِنَّا نَخَافُ مِن رَّبِّنَا يَوۡمًا عَبُوسٗا قَمۡطَرِيرٗا","5601":"فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلۡيَوۡمِ وَلَقَّىٰهُمۡ نَضۡرَةٗ وَسُرُورٗا","5602":"وَجَزَىٰهُم بِمَا صَبَرُواْ جَنَّةٗ وَحَرِيرٗا","6007":"فَأَمَّا ٱلۡإِنسَٰنُ إِذَا مَا ٱبۡتَلَىٰهُ رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّيٓ أَكۡرَمَنِ","6008":"وَأَمَّآ إِذَا مَا ٱبۡتَلَىٰهُ فَقَدَرَ عَلَيۡهِ رِزۡقَهُۥ فَيَقُولُ رَبِّيٓ أَهَٰنَنِ","6009":"كـَلَّاۖ بَل لَّا تُكۡرِمُونَ ٱلۡيَتِيمَ","6010":"وَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","6011":"وَتَأۡكُلُونَ ٱلتُّرَاثَ أَكۡلٗا لَّمّٗا","6012":"وَتُحِبُّونَ ٱلۡمَالَ حُبّٗا جَمّٗا","6033":"فَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ","6034":"وَمَآ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ","6035":"فَكُّ رَقَبَةٍ","6036":"أَوۡ إِطۡعَٰمٞ فِي يَوۡمٖ ذِي مَسۡغَبَةٖ","6037":"يَتِيمٗا ذَا مَقۡرَبَةٍ","6038":"أَوۡ مِسۡكِينٗا ذَا مَتۡرَبَةٖ","6039":"ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُواْ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ وَتَوَاصَوۡاْ بِٱلۡمَرۡحَمَةِ","6040":"أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡمَيۡمَنَةِ","6195":"فَلۡيَعۡبُدُواْ رَبَّ هَٰذَا ٱلۡبَيۡتِ","6196":"ٱلَّذِيٓ أَطۡعَمَهُم مِّن جُوعٖ وَءَامَنَهُم مِّنۡ خَوۡفِۭ","6197":"أَرَءَيۡتَ ٱلَّذِي يُكَذِّبُ بِٱلدِّينِ","6198":"فَذَٰلِكَ ٱلَّذِي يَدُعُّ ٱلۡيَتِيمَ","6199":"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","6200":"فَوَيۡلٞ لِّلۡمُصَلِّينَ","6201":"ٱلَّذِينَ هُمۡ عَن صَلَاتِهِمۡ سَاهُونَ","6202":"ٱلَّذِينَ هُمۡ يُرَآءُونَ","6203":"وَيَمۡنَعُونَ ٱلۡمَاعُونَ"},"h":{"tutim":{"id":"tutim","t":"أي الإسلام خير: تطعم الطعام","x":"تُطْعِمُ الطَّعَامَ، وَتَقْرَأُ السَّلاَمَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ","b":"bukhari","k":"12","gr":"صحيح","en":"A man asked the Prophet ﷺ: \"Which Islam is best?\" He said: \"That you feed food, and give the greeting of peace to those you know and those you do not know.\""},"jai":{"id":"jai","t":"فكّوا العاني وأطعموا الجائع","x":"فُكُّوا الْعَانِيَ ـ يَعْنِي الأَسِيرَ ـ وَأَطْعِمُوا الْجَائِعَ وَعُودُوا الْمَرِيضَ","b":"bukhari","k":"3046","gr":"صحيح","en":"\"Free the captive\" — meaning the prisoner — \"feed the hungry, and visit the sick.\""},"ijtama":{"id":"ijtama","t":"ما اجتمعن في امرئ إلا دخل الجنة","x":"مَنْ أَصْبَحَ مِنْكُمُ الْيَوْمَ صَائِمًا \" . قَالَ أَبُو بَكْرٍ رضى الله عنه أَنَا . قَالَ \" فَمَنْ تَبِعَ مِنْكُمُ الْيَوْمَ جَنَازَةً \" . قَالَ أَبُو بَكْرٍ رضى الله عنه أَنَا . قَالَ \" فَمَنْ أَطْعَمَ مِنْكُمُ الْيَوْمَ مِسْكِينًا \" . قَالَ أَبُو بَكْرٍ رضى الله عنه أَنَا . قَالَ \" فَمَنْ عَادَ مِنْكُمُ الْيَوْمَ مَرِيضًا \" . قَالَ أَبُو بَكْرٍ رضى الله عنه أَنَا . فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم \" مَا اجْتَمَعْنَ فِي امْرِئٍ إِلاَّ دَخَلَ الْجَنَّةَ","b":"muslim","k":"1028","gr":"صحيح","en":"\"Who among you is fasting today?\" Abu Bakr said: \"I am.\" He said: \"Who among you has followed a funeral today?\" Abu Bakr said: \"I have.\" He said: \"Who among you has fed a poor person today?\" Abu Bakr said: \"I have.\" He said: \"Who among you has visited a sick person today?\" Abu Bakr said: \"I have.\" The Messenger of Allah ﷺ said: \"These do not gather in a person but he enters Paradise.\""},"istatam":{"id":"istatam","t":"استطعمتك فلم تطعمني","x":"يَا ابْنَ آدَمَ اسْتَطْعَمْتُكَ فَلَمْ تُطْعِمْنِي . قَالَ يَا رَبِّ وَكَيْفَ أُطْعِمُكَ وَأَنْتَ رَبُّ الْعَالَمِينَ . قَالَ أَمَا عَلِمْتَ أَنَّهُ اسْتَطْعَمَكَ عَبْدِي فُلاَنٌ فَلَمْ تُطْعِمْهُ أَمَا عَلِمْتَ أَنَّكَ لَوْ أَطْعَمْتَهُ لَوَجَدْتَ ذَلِكَ عِنْدِي","b":"muslim","k":"2569","gr":"صحيح","en":"\"O son of Adam, I asked you for food and you did not feed Me.\" He says: \"My Lord, how could I feed You when You are the Lord of the worlds?\" He says: \"Did you not know that My servant so-and-so asked you for food and you did not feed him? Did you not know that had you fed him you would have found that with Me?\""},"dayf":{"id":"dayf","t":"من كان يؤمن بالله واليوم الآخر فليكرم ضيفه","x":"مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيُكْرِمْ ضَيْفَهُ، جَائِزَتُهُ يَوْمٌ وَلَيْلَةٌ، وَالضِّيَافَةُ ثَلاَثَةُ أَيَّامٍ، فَمَا بَعْدَ ذَلِكَ فَهْوَ صَدَقَةٌ","b":"bukhari","k":"6135","gr":"صحيح","en":"\"Whoever believes in Allah and the Last Day, let him honour his guest; his due is a day and a night, and hospitality is three days, and what is beyond that is charity.\""},"haqq":{"id":"haqq","t":"فخذوا منهم حق الضيف","x":"إِنْ نَزَلْتُمْ بِقَوْمٍ، فَأُمِرَ لَكُمْ بِمَا يَنْبَغِي لِلضَّيْفِ فَاقْبَلُوا، فَإِنْ لَمْ يَفْعَلُوا فَخُذُوا مِنْهُمْ حَقَّ الضَّيْفِ","b":"bukhari","k":"2461","gr":"صحيح","en":"\"If you stay with a people and they order for you what is fitting for a guest, accept it; and if they do not, take from them the guest's due.\""},"abutalha":{"id":"abutalha","t":"لقد عجب الله من فلان وفلانة","x":"أَتَى رَجُلٌ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقَالَ يَا رَسُولَ اللَّهِ أَصَابَنِي الْجَهْدُ فَأَرْسَلَ إِلَى نِسَائِهِ فَلَمْ يَجِدْ عِنْدَهُنَّ شَيْئًا، فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم \" أَلاَ رَجُلٌ يُضَيِّفُ هَذِهِ اللَّيْلَةَ يَرْحَمُهُ اللَّهُ \". فَقَامَ رَجُلٌ مِنَ الأَنْصَارِ فَقَالَ أَنَا يَا رَسُولَ اللَّهِ. فَذَهَبَ إِلَى أَهْلِهِ فَقَالَ لاِمْرَأَتِهِ ضَيْفُ رَسُولِ اللَّهِ صلى الله عليه وسلم لاَ تَدَّخِرِيهِ شَيْئًا. قَالَتْ وَاللَّهِ مَا عِنْدِي إِلاَّ قُوتُ الصِّبْيَةِ. قَالَ فَإِذَا أَرَادَ الصِّبْيَةُ الْعَشَاءَ فَنَوِّمِيهِمْ، وَتَعَالَىْ فَأَطْفِئِي السِّرَاجَ وَنَطْوِي بُطُونَنَا اللَّيْلَةَ. فَفَعَلَتْ ثُمَّ غَدَا الرَّجُلُ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ \" لَقَدْ عَجِبَ اللَّهُ عَزَّ وَجَلَّ ـ أَوْ ضَحِكَ ـ مِنْ فُلاَنٍ وَفُلاَنَةَ","b":"bukhari","k":"4889","gr":"صحيح","en":"A man came to the Messenger of Allah ﷺ and said: \"O Messenger of Allah, hardship has afflicted me.\" He sent to his wives but found nothing with them. The Messenger of Allah ﷺ said: \"Is there no man who will host this one tonight, Allah have mercy on him?\" A man of the Ansar stood and said: \"I will, O Messenger of Allah.\" He went to his wife and said: \"The guest of the Messenger of Allah ﷺ — keep nothing back from him.\" She said: \"By Allah, I have nothing but the children's food.\" He said: \"When the children want their supper, put them to sleep, then come and put out the lamp, and we shall go hungry tonight.\" She did so. Then the man went in the morning to the Messenger of Allah ﷺ, who said: \"Allah marvelled — or laughed — at so-and-so and so-and-so.\""},"walima":{"id":"walima","t":"إذا دُعي أحدكم إلى الوليمة فليأتها","x":"إِذَا دُعِيَ أَحَدُكُمْ إِلَى الْوَلِيمَةِ فَلْيَأْتِهَا","b":"bukhari","k":"5173","gr":"صحيح","en":"\"When one of you is invited to the wedding feast, let him come to it.\""},"budn":{"id":"budn","t":"قسمة لحوم الهدي على المساكين","x":"أَمَرَهُ أَنْ يَقُومَ عَلَى بُدْنِهِ وَأَمَرَهُ أَنْ يَقْسِمَ بُدْنَهُ كُلَّهَا لُحُومَهَا وَجُلُودَهَا وَجِلاَلَهَا فِي الْمَسَاكِينِ","b":"muslim","k":"1317","gr":"صحيح","en":"The Prophet of Allah ﷺ commanded him to see to his sacrificial camels and commanded him to distribute all of them — their meat, their hides and their covers — among the poor."},"farha":{"id":"farha","t":"للصائم فرحتان","x":"قَالَ اللَّهُ كُلُّ عَمَلِ ابْنِ آدَمَ لَهُ إِلاَّ الصِّيَامَ، فَإِنَّهُ لِي، وَأَنَا أَجْزِي بِهِ. وَالصِّيَامُ جُنَّةٌ، وَإِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ، فَلاَ يَرْفُثْ وَلاَ يَصْخَبْ، فَإِنْ سَابَّهُ أَحَدٌ، أَوْ قَاتَلَهُ فَلْيَقُلْ إِنِّي امْرُؤٌ صَائِمٌ. وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ، لِلصَّائِمِ فَرْحَتَانِ يَفْرَحُهُمَا إِذَا أَفْطَرَ فَرِحَ، وَإِذَا لَقِيَ رَبَّهُ فَرِحَ بِصَوْمِهِ","b":"bukhari","k":"1904","gr":"صحيح","en":"Allah said: \"Every deed of the son of Adam is for him, except fasting, for it is Mine and I reward for it. Fasting is a shield. On the day one of you fasts, let him not use foul speech nor shout; and if someone insults him or fights him, let him say: I am a fasting man. By Him in whose hand is the soul of Muhammad, the odour of the fasting person's mouth is better with Allah than the scent of musk. The fasting person has two joys: when he breaks his fast he rejoices, and when he meets his Lord he rejoices in his fast.\""},"tasahharu":{"id":"tasahharu","t":"تسحّروا فإن في السحور بركة","x":"تَسَحَّرُوا فَإِنَّ فِي السَّحُورِ بَرَكَةً","b":"bukhari","k":"1923","gr":"صحيح","en":"\"Eat the pre-dawn meal, for in the pre-dawn meal there is blessing.\""},"ajjalu":{"id":"ajjalu","t":"لا يزال الناس بخير ما عجلوا الفطر","x":"لاَ يَزَالُ النَّاسُ بِخَيْرٍ مَا عَجَّلُوا الْفِطْرَ","b":"bukhari","k":"1957","gr":"صحيح","en":"\"People will remain in good as long as they hasten the breaking of the fast.\""}},"nay":111,"nq":36,"nh":12};
